function rgba(hex,a=1){const n=parseInt(hex.slice(1),16);return`rgba(${n>>16},${n>>8&255},${n&255},${a})`}function hash(x,y){const n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)}
const rain=Array.from({length:110},()=>({x:rand(0,900),y:rand(0,600),v:rand(90,180)}));
function drawTree(x,y,s=1,kind=0){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#18271b';ctx.fillRect(-3,1,7,9);ctx.fillStyle=kind?'#465d37':'#536b3e';ctx.fillRect(-11,-9,22,10);ctx.fillRect(-8,-15,16,8);ctx.fillStyle='#70824a';ctx.fillRect(-5,-14,7,3);ctx.fillStyle='#344a30';ctx.fillRect(-15,-6,5,6);ctx.fillRect(10,-5,6,6);ctx.restore()}
function drawBuilding(p){ctx.save();ctx.translate(p.x,p.y);if(p.kind==='pad'){ctx.fillStyle='#a69a6d';ctx.fillRect(-27,-10,54,23);ctx.fillStyle='#d3c88e';ctx.fillRect(-24,-8,48,18);ctx.fillStyle='#78805c';ctx.fillRect(-5,-3,10,7);ctx.fillStyle='#e6d9a1';ctx.fillRect(-2,-18,4,8);ctx.fillRect(-12,-14,24,2)}else if(p.kind==='visitor'||p.kind==='lab'){ctx.fillStyle='#24342b';ctx.fillRect(-30,-20,60,30);ctx.fillStyle=p.kind==='lab'?'#78918a':'#a48a56';ctx.fillRect(-26,-22,52,9);ctx.fillStyle='#d5c27c';ctx.fillRect(-21,-10,8,12);ctx.fillRect(-5,-10,8,12);ctx.fillRect(13,-10,8,12);ctx.fillStyle='#526553';ctx.fillRect(-33,8,66,4);ctx.fillStyle='#ddd0a0';ctx.fillRect(-4,-18,8,4)}else if(p.kind==='fence'){ctx.strokeStyle='#c2b58a';ctx.lineWidth=2;ctx.strokeRect(-47,-21,94,42);ctx.lineWidth=1;for(let x=-42;x<48;x+=12){ctx.beginPath();ctx.moveTo(x,-21);ctx.lineTo(x,21);ctx.stroke()}ctx.fillStyle='#785a3b';ctx.fillRect(-13,-12,28,21);ctx.fillStyle='#c9a967';ctx.fillRect(-16,-16,34,6);ctx.fillStyle='#cf5842';ctx.fillRect(14,-22,13,4)}else if(p.kind==='lake'){ctx.fillStyle='#294536';ctx.beginPath();ctx.ellipse(0,0,55,33,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#477c73';ctx.beginPath();ctx.ellipse(0,-2,47,26,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9bb49a';ctx.fillRect(-28,-7,15,2);ctx.fillRect(11,7,22,2)}else{ctx.fillStyle='#78664b';ctx.fillRect(-25,-5,50,12);ctx.fillStyle='#d3bf84';ctx.fillRect(-21,-10,42,5);ctx.fillStyle='#526b48';ctx.fillRect(-17,7,34,3)}ctx.restore()}
function drawGround(camX,camY,vw,vh){ctx.fillStyle='#344c32';ctx.fillRect(0,0,vw,vh);const tile=32;for(let y=Math.floor(camY/tile);y<Math.ceil((camY+vh)/tile);y++)for(let x=Math.floor(camX/tile);x<Math.ceil((camX+vw)/tile);x++){const h=hash(x,y),sx=x*tile-camX,sy=y*tile-camY;ctx.fillStyle=h>.78?'#405b38':h<.13?'#30482f':'#385333';ctx.fillRect(sx,sy,tile,tile);if(h>.88){ctx.fillStyle='#536743';ctx.fillRect(sx+7,sy+11,3,2);ctx.fillRect(sx+21,sy+24,2,2)}}
// meandering pale service paths
ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#8c8059';ctx.lineWidth=22;ctx.beginPath();ctx.moveTo(390,790);ctx.bezierCurveTo(470,765,570,735,720,690);ctx.bezierCurveTo(820,650,920,570,1100,510);ctx.bezierCurveTo(1280,520,1410,625,1570,690);ctx.moveTo(720,690);ctx.bezierCurveTo(730,850,760,970,790,1110);ctx.moveTo(790,1110);ctx.bezierCurveTo(950,1100,1090,1050,1200,1010);ctx.moveTo(1200,1010);ctx.bezierCurveTo(1390,870,1550,620,1570,690);ctx.moveTo(1570,690);ctx.bezierCurveTo(1710,580,1820,440,1930,360);ctx.stroke();ctx.strokeStyle='#c2ad73';ctx.lineWidth=2;ctx.setLineDash([6,8]);ctx.stroke();ctx.setLineDash([]);
ctx.fillStyle='#253f31';ctx.beginPath();ctx.ellipse(790-camX,1110-camY,70,42,-.25,0,Math.PI*2);ctx.fill();ctx.fillStyle='#477a70';ctx.beginPath();ctx.ellipse(790-camX,1108-camY,58,32,-.25,0,Math.PI*2);ctx.fill();
// forest boundary and scattered vegetation
for(let i=0;i<165;i++){const x=hash(i,8)*world.w,y=hash(i,19)*world.h;if(Math.hypot(x-player.x,y-player.y)>0||true){if(x<camX-50||x>camX+vw+50||y<camY-50||y>camY+vh+50)continue;const s=.7+hash(i,4)*.7;drawTree(x-camX,y-camY,s,i%4===0)}}
points.forEach((p,i)=>{drawBuilding({...p,x:p.x-camX,y:p.y-camY});ctx.fillStyle=i<unlocked?'#e7d28f':'#b8bd9b';ctx.font='7px monospace';ctx.textAlign='center';ctx.fillText(p.name,p.x-camX,p.y-camY+32)});
built.forEach((b,i)=>drawBuilt(b,camX,camY,i))}
function drawBuilt(b,cx,cy,i){const x=b.x-cx,y=b.y-cy;ctx.save();ctx.translate(x,y);switch(b.kind){case'cerca':ctx.strokeStyle='#d7c391';ctx.lineWidth=2;ctx.strokeRect(-18,-12,36,24);for(let n=-14;n<=14;n+=9){ctx.beginPath();ctx.moveTo(n,-12);ctx.lineTo(n,12);ctx.stroke()}break;case'árvore':drawTree(0,0,1.1);break;case'lago':ctx.fillStyle='#58938b';ctx.beginPath();ctx.ellipse(0,0,23,13,0,0,7);ctx.fill();break;case'estrada':ctx.fillStyle='#a89767';ctx.fillRect(-24,-4,48,8);break;case'dino':drawDino({type:1,x:b.x,y:b.y,dir:1,walk:elapsed*4,scale:.7},cx,cy);break;default:ctx.fillStyle='#88734e';ctx.fillRect(-17,-13,34,25);ctx.fillStyle='#c3a568';ctx.fillRect(-20,-17,40,6);ctx.fillStyle='#63795c';ctx.fillRect(-11,-7,7,10);ctx.fillRect(5,-7,7,10)}ctx.restore()}

